 function aim(ctx,u,i,point){if(i!==0)return false;let p=P().Q,angle=Math.atan2(point.y-u.y,point.x-u.x),offset=0;ctx.save();ctx.translate(u.x,u.y);ctx.rotate(angle);for(let n=0;n<p.strike_count;n++){offset+=p.step_distances[n];ctx.fillStyle=['#9ee6ac20','#d8e9b030','#efffb545'][n];ctx.strokeStyle=['#75d79b','#bcdf9d','#efffb5'][n];ctx.lineWidth=2;ctx.fillRect(offset,-p.width/2,p.hit_range,p.width);ctx.strokeRect(offset,-p.width/2,p.hit_range,p.width);ctx.fillStyle='#f3ffe5';ctx.font='bold 15px Arial';ctx.fillText(String(n+1),offset+8,-p.width/2-8)}ctx.restore();return true}
 function draw(ctx,viewer){for(let u of units())if(u.hero===ID){let s=state(u);for(let[id,v]of s.vitals){let t=units().find(t=>t.id===id);if(!alive(t)||!v.active||s.action?.kind==='R'&&s.action.target===t)continue;ctx.save();ctx.translate(t.x,t.y);ctx.strokeStyle='#c4ff8bcc';ctx.lineWidth=6;ctx.beginPath();ctx.arc(0,0,(t.radius||25)+20,angles[v.direction]-.45,angles[v.direction]+.45);ctx.stroke();ctx.restore()}let a=s.action;if(a?.kind==='R'&&alive(a.target))for(let i=a.fired;i<P().R.vitals_revealed;i++){ctx.beginPath();ctx.arc(a.target.x,a.target.y,(a.target.radius||25)+25,angles[i]-.42,angles[i]+.42);ctx.strokeStyle='#e7fba5';ctx.lineWidth=5;ctx.stroke()}for(let f of s.fields){ctx.beginPath();ctx.arc(f.x,f.y,f.radius,0,Math.PI*2);ctx.fillStyle='#78e98725';ctx.fill();ctx.strokeStyle='#a9ffc3aa';ctx.lineWidth=3;ctx.stroke()}if(s.eActive){ctx.beginPath();ctx.arc(u.x,u.y,42,0,Math.PI*2);ctx.strokeStyle='#61fba18a';ctx.lineWidth=4;ctx.stroke()}for(let v of s.visuals){ctx.save();ctx.translate(v.x,v.y);if(v.kind==='slash'){ctx.rotate(v.angle);ctx.strokeStyle=v.index===2?'#d9ffb4':'#9ce6ac';ctx.lineWidth=8;ctx.beginPath();if(v.index===0)ctx.arc(0,0,125,-.8,.8);else if(v.index===1){ctx.moveTo(125,-65);ctx.lineTo(40,45)}else{ctx.moveTo(30,45);ctx.quadraticCurveTo(160,-30,75,-130)}ctx.stroke();for(let j=0;j<5;j++){ctx.fillStyle='#70462e';ctx.fillRect(65+j*10,Math.sin(j*2)*35,5,5)}}else{ctx.strokeStyle=v.kind==='vital'?'#fff9b3':'#9fffbf';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,35,0,Math.PI*2);ctx.stroke()}ctx.restore()}}}
 function bot(u,t){let s=state(u);if(s.action)return true;if(u.hp/u.maxHp<.6&&u.skillRanks[1]&&u.cd[1]<=0)return m.requestCast(u,1,u);if(champion(t)&&u.skillRanks[3]&&u.cd[3]<=0&&dist(u,t)<=u.skills[3].range&&m.healthCosts.canPay(u,cost(u,3).amount))return m.requestCast(u,3,t);if(u.skillRanks[0]&&u.cd[0]<=0&&dist(u,t)<=u.skills[0].range&&m.healthCosts.canPay(u,cost(u,0).amount))return m.requestCast(u,0,t);if(!s.eActive&&u.skillRanks[2]&&u.cd[2]<=0&&dist(u,t)>u.range&&m.healthCosts.canPay(u,cost(u,2).amount,cost(u,2).minimum))return m.requestCast(u,2,u);return false}
